const moveLiveRunners = `-- name: MoveLiveRunners :execrows
update runners set trigger_job_id = $1
where trigger_job_id = $2 and state <> 'finished'
`

type MoveLiveRunnersParams struct {
	ToJobID   *int64
	FromJobID *int64
}

// Hands a job's spare runner to another job that lost its own.
func (q *Queries) MoveLiveRunners(ctx context.Context, arg MoveLiveRunnersParams) (int64, error) {
	result, err := q.db.Exec(ctx, moveLiveRunners, arg.ToJobID, arg.FromJobID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

